);

CREATE TABLE line_result (
	run_id INTEGER NOT NULL, 
	study VARCHAR(32) NOT NULL, 
	scenario_id INTEGER NOT NULL, 
	line_id VARCHAR(64) NOT NULL, 
	flow_mw FLOAT NULL, 
	loading FLOAT NULL, 
	binding BIT NULL, 
	PRIMARY KEY (run_id, study, scenario_id, line_id), 
	FOREIGN KEY(run_id, study, scenario_id) REFERENCES scenario (run_id, study, scenario_id), 
	FOREIGN KEY(line_id) REFERENCES line (line_id)
);

CREATE TABLE n1_delta_lmp (
	run_id INTEGER NOT NULL, 
